import {receiptGroups,receiptTotals,selectedPerformance,sampleVendors,periodRange,matches} from './purchaseCore.mjs';
import {emptyPlan,validatePlan,carryForward,nextMonth,fields,statuses} from './priorities.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>v===null||v===undefined?'—':new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(v);
const pct=v=>v===null||v===undefined?'—':`${v.toFixed(1)}%`;
const money=(v,currency)=>v===null||v===undefined?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:currency||'USD',maximumFractionDigits:0}).format(v);
const nice=day=>new Date(day+'T00:00:00Z').toLocaleDateString('en-US',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'});
const monthNice=month=>new Date(month+'-01T00:00:00Z').toLocaleDateString('en-US',{timeZone:'UTC',month:'short',year:'numeric'});
const labels=['Priority','Vendor / Category','Markup target %','Sell-Through target %','Units Goal','Success Measure','What Success Looks Like?','Status','Next Step','Results'];
let data,config,groups=[],audit=[],reviews={},reviewIndex=0,attention=false,plan,planMode='local',loadSequence=0;
const filters=()=>({store:$('store').value,brand:$('brand').value,vendor:$('vendor').value,type:$('periodType').value,period:$('period').value});
function options(id,values,allLabel){const previous=$(id).value;$(id).innerHTML=(allLabel?`<option value="all">${esc(allLabel)}</option>`:'')+values.map(v=>`<option value="${esc(v.value??v)}">${esc(v.label??v)}</option>`).join('');if([...$(id).options].some(o=>o.value===previous))$(id).value=previous;}
function refreshPeriods(){const months=[];for(let m=data.meta.startDate.slice(0,7);m<=data.asOf.slice(0,7);m=nextMonth(m))months.push(m);let values;
  if($('periodType').value==='month')values=months.map(m=>({value:m,label:monthNice(m)}));
  else if($('periodType').value==='quarter')values=[...new Set(months.map(m=>`${m.slice(0,4)}-Q${Math.ceil(Number(m.slice(5))/3)}`))];
  else values=[...new Set(months.map(m=>m.slice(0,4)))].map(y=>({value:y,label:`${y} · YTD`}));
  options('period',values);$('period').selectedIndex=$('period').options.length-1;
}
function refreshDimensions(){const list=[...data.catalog,...data.receipts,...data.sales].filter(r=>$('store').value==='all'||r.store===$('store').value);options('brand',[...new Set(list.map(r=>r.brand||'Unspecified'))].sort(),'All brands');options('vendor',[...new Set(list.filter(r=>$('brand').value==='all'||(r.brand||'Unspecified')===$('brand').value).map(r=>r.vendor))].sort(),'All vendors');}
function kpi(label,value,note,icon='◈',tone=''){return `<article class="kpi"><div class="kpi-top"><span>${label}</span><span class="kpi-icon" aria-hidden="true">${icon}</span></div><div class="kpi-value ${value==='Source required'||value==='No receipts'?'unavailable':tone}">${value}</div><small>${note}</small></article>`;}
const classRate=value=>value>=config.strongThreshold?'good':value<config.attentionThreshold?'bad':'warning';
function render(){const f=filters(),range=periodRange(f.type,f.period,data.asOf);groups=receiptGroups(data,f);const totals=receiptTotals(groups),perf=selectedPerformance(data,f);
  const inventory=new URL(config.inventoryUrl);if(f.store!=='all')inventory.searchParams.set('store',f.store);if(f.vendor!=='all')inventory.searchParams.set('vendor',f.vendor);inventory.searchParams.set('period',range.start.slice(0,7));$('inventoryLink').href=inventory;$('inventoryNav').href=inventory;
  $('rangeLabel').textContent=`${nice(range.start)} – ${nice(range.end)} · ${f.store==='all'?'Corro + Cavali':data.meta.stores[f.store]?.label||f.store}`;
  const sourceMissing=Object.entries(data.meta.stores).filter(([s])=>f.store==='all'||f.store===s).filter(([,s])=>s.receiptPermissions?.purchaseOrders===false).map(([s])=>data.meta.stores[s].label||s);
  $('sourceNote').innerHTML=`<div><strong>${sourceMissing.length?'Purchase-order access needs attention':groups.length?'Supplier receipt records available':'No confirmed receipts in this selection'}</strong><p>${sourceMissing.length?`${esc(sourceMissing.join(' + '))}: the imported sync was denied access to purchase orders. Receipt units, cost and sell-through cannot yet be confirmed.`:groups.length?'Receipt dates and quantities come from the imported source. SKU FIFO allocation is shown separately from physical lot verification.':'The export contains sales and stock history, but no dated supplier receipts for these filters.'}</p></div><button class="secondary" id="inspectSource">Review source</button>`;
  $('inspectSource').onclick=openSources;
  $('purchaseKpis').innerHTML=kpi('Units In',totals.units===null?'No receipts':number(totals.units),'Confirmed supplier receipts in the selected period','↙')+kpi('COGS Value',totals.cost===null?'Source required':money(totals.cost,totals.currency),'Receipt value · documented unit cost only','◇')+kpi('General Markup',totals.markup===null?'Source required':pct(totals.markup),'Weighted current retail vs. receipt cost · not gross margin','↗')+kpi('Sell-Through · 90d',totals.rate90===null?'Source required':pct(totals.rate90),`${totals.mature} mature vendor/date groups · ${totals.remaining90===null?'unsold count requires receipts':number(totals.remaining90)+' units unsold at day 90'} · FIFO`,'◷',totals.rate90!==null&&totals.rate90<config.attentionThreshold?'negative':'positive');
  $('contextPeriod').textContent=`All stock · ${nice(range.start)} to ${nice([range.end,data.asOf].sort()[0])}${range.end>data.asOf?' · In Progress':''}`;
  $('businessKpis').innerHTML=kpi('Units Sold · net',perf.net===null?'Source required':number(perf.net),`${perf.ordered===null?'Incomplete period coverage':number(perf.ordered)+' ordered before reversals'} · selected period`,'▤')+kpi('COGS · sold',perf.cost===null?'Source required':money(perf.cost,perf.currency),'Shopify transaction COGS · selected period','◇')+kpi('Gross Profit 1',perf.grossProfit===null?'Source required':money(perf.grossProfit,perf.currency),'Net sales after discounts and reversals − COGS','↗',perf.grossProfit!==null&&perf.grossProfit<0?'negative':'positive')+kpi('Catalog Markup',perf.catalogMarkup===null?'Source required':pct(perf.catalogMarkup),'Current in-stock catalog · valid price/cost items · context only','◈');
  if(config.showDiscounts)$('businessKpis').innerHTML+=kpi('Discounts',perf.discounts===null?'Source required':money(perf.discounts,perf.currency),'Shopify discounts · already included in net sales','%');
  renderReceipts();renderSources();audit=sampleVendors(data,f);loadReviews();renderAudit();
}
function renderReceipts(){const visible=attention?groups.filter(g=>g.windows[90].status==='ready'&&g.windows[90].pct<config.attentionThreshold):groups;
  $('receiptEmpty').hidden=visible.length>0;
  $('receiptEmpty').innerHTML=visible.length?'':`<div class="empty-icon" aria-hidden="true">◇</div><h3>${attention?'No completed receipts match this alert':'Receipt performance needs dated purchase records'}</h3><p>${attention?'Only completed 90-day windows are evaluated. In Progress windows are not marked as underperforming.':'The export has no confirmed supplier receipts for this selection. Customer returns and positive stock adjustments are kept separate. Import confirmed SKU quantities and receipt dates to populate this table.'}</p>`;
  $('receiptCount').textContent=`${visible.length} vendor / date groups · ${groups.length} in selection · ${config.attentionThreshold}% / ${config.strongThreshold}% visual guides, not approved targets`;
  $('receipts').innerHTML=visible.length?visible.map(g=>`<tr><td><details><summary>${esc(g.vendor)}</summary><div class="sku-lines">${g.rows.map(r=>`<div><strong>${esc(r.sku||'SKU unavailable')}</strong><small>${esc(r.product)} · ${number(r.unitsReceived)} received</small><small>${esc(r.costBasis||'Receipt cost absent')}</small></div>`).join('')}</div></details><small>${esc(data.meta.stores[g.store]?.label||g.store)} · ${g.rows.length} SKU entries</small><a class="text-button" href="${esc(new URL(`?store=${encodeURIComponent(g.store)}&vendor=${encodeURIComponent(g.vendor)}&period=${g.date.slice(0,7)}`,config.inventoryUrl).href)}">Monthly detail ↗</a></td><td><strong>${number(g.units)}</strong></td><td>${money(g.cost,g.currency)}<small>${g.cost===null?'Receipt cost absent':esc(g.currency)+' · documented cost'}</small></td><td>${pct(g.markup)}<small>Current retail / receipt cost</small></td><td>${nice(g.date)}</td>${[30,60,90].map(d=>{const w=g.windows[d];return `<td>${w.units===null?'—':number(w.units)}<small>${w.status==='pending'?'In Progress':w.status==='unavailable'?'Incomplete source':'Through '+nice(w.end)}</small></td><td>${w.pct===null?'—':`<span class="badge ${w.status==='ready'?classRate(w.pct):'warning'}">${pct(w.pct)}${w.status==='pending'?' so far':''}</span>`}</td>`;}).join('')}<td>${number(g.remaining90)}<small>${g.remaining90===null?'90d window incomplete':'FIFO units at day 90'}</small></td></tr>`).join(''):'';
}
function renderSources(){const stores=Object.entries(data.meta.stores);$('sourceDetails').innerHTML=`<h3>Current export</h3><p>Generated ${esc(data.meta.generatedAt)}. Reporting history begins ${esc(data.meta.startDate)}; common complete sales date ${esc(data.asOf)}. ${data.receipts.length} confirmed receipt SKU rows, ${data.observed.length} observed additions, ${data.customerReturnCount} customer-return entries.</p><h3>Source access</h3>${stores.map(([key,s])=>`<p><strong>${esc(s.label||key)}</strong> · Sales through ${esc(s.salesThrough)}<br>${esc(s.purchaseOrderError||'No purchase-order access error recorded in this export.')}</p>`).join('')}<p>Shopify requires <code>read_inventory_purchase_orders</code> and permission to view purchase orders. The existing extractor requests receipts again on every sync; after access is corrected, run it and replace the complete export folder. An order creation date alone is never used as a receipt date.</p><h3>Observed additions</h3>${data.observed.length?`<div class="table-scroll"><table><thead><tr><th>Vendor / Store</th><th>SKU</th><th>Observed units</th><th>Date</th></tr></thead><tbody>${data.observed.filter(r=>matches(r,filters())).map(r=>`<tr><td>${esc(r.vendor)} · ${esc(r.store)}</td><td>${esc(r.sku)}</td><td>${number(r.unitsReceived)}</td><td>${esc(r.cohortDate)}</td></tr>`).join('')||'<tr><td colspan="4">No observed additions for these store / brand / vendor filters.</td></tr>'}</tbody></table></div>`:'<p>No observed additions in this export.</p>'}<p>Observed additions are not included in purchase KPIs. Their exact purchase link is absent.</p><h3>Calculation rules</h3><ul><li>30 days includes the receipt date through day 29; 60 and 90 end on days 59 and 89. Windows overlap and must not be added.</li><li>SKU FIFO consumes opening stock first, then dated receipts and returned stock. Each ordered unit is allocated once. This is a model, not proof of the physical batch sold.</li><li>Missing opening stock or incomplete sales history prevents a receipt percentage. In Progress means the window has not finished; values are explicitly marked “so far”.</li><li>COGS Value is the cost of receipts. COGS sold and Gross Profit 1 use Shopify sales metrics; catalog cost never fills missing transaction cost.</li><li>General Markup uses receipt cost and current retail, weighted by units. Catalog Markup uses the current stock snapshot. Neither is gross margin.</li><li>YTD begins January 1. If earlier history is absent, sales totals are withheld rather than relabeled as a complete YTD. Receipt rows show only the available history.</li><li>Brand is an explicit product field, independent of Store and Vendor. The extractor reads a text field named custom.brand; absent values are Unspecified.</li><li>Currency totals are withheld if currencies differ or are missing. Discounts are disabled by default; they can be enabled in site-config.json and are never subtracted twice.</li></ul>`;}
function openSources(){$('sources').open=true;$('sources').scrollIntoView({behavior:'smooth',block:'start'});}
function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const csv=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
function exportReceipts(){const header=['Store','Vendor','Units In','COGS Value','Currency','Markup % at current retail','Date Received',...[30,60,90].flatMap(d=>[`${d}d units`,`${d}d %`,`${d}d status`]),'Unsold at 90d'];const rows=groups.map(g=>[g.store,g.vendor,g.units,g.cost,g.currency,g.markup,g.date,...[30,60,90].flatMap(d=>[g.windows[d].units,g.windows[d].pct,g.windows[d].status]),g.remaining90]);download(`purchase-receipts-${filters().period}.csv`,[header,...rows].map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
const planKey=month=>`purchase-plan-v1:${month}`;
function localPlan(month){const saved=localStorage.getItem(planKey(month));if(!saved)return emptyPlan(month);try{return validatePlan(JSON.parse(saved));}catch{throw Error('Saved plan could not be read. Preserve the browser backup before replacing it.');}}
async function fetchPlan(month){const res=await fetch(`api/priorities?month=${encodeURIComponent(month)}`,{cache:'no-store'});if([404,503].includes(res.status))return {mode:'local',plan:localPlan(month)};const body=await res.json();if(!res.ok)throw Error(body.error||'Shared plan access failed');return {mode:'shared',plan:validatePlan(body)};}
async function loadPlan(month){const sequence=++loadSequence;$('savePlan').disabled=true;$('carryPlan').disabled=true;
  try{const result=await fetchPlan(month);if(sequence!==loadSequence)return;plan=result.plan;planMode=result.mode;$('planMessage').textContent='';}
  catch(error){if(sequence!==loadSequence)return;try{plan=localPlan(month);}catch{plan=emptyPlan(month);}planMode='error';$('planMessage').textContent=error.message+' · Local draft available; shared save is disabled.';}
  if(sequence!==loadSequence)return;$('planMode').textContent=planMode==='shared'?'Shared workspace · save changes for the team':planMode==='local'?'Local browser plan · use Backup to share or preserve it':'Local draft · shared connection needs attention';$('savePlan').disabled=planMode==='error';$('carryPlan').disabled=planMode==='error';renderPlan();
}
function renderPlan(){$('planRows').innerHTML=plan.rows.map((r,i)=>`<tr class="plan-row ${i===0?'expanded':''}">${fields.map((field,j)=>`<td data-label="${labels[j]}">${j===0?`<button type="button" class="priority-number plan-toggle" aria-expanded="${i===0}" data-toggle="${i}">PRIORITY ${String(i+1).padStart(2,'0')}${r.carriedFrom?' · CARRIED FORWARD':''}<span aria-hidden="true">⌄</span></button>`:''}${field==='status'?`<select data-row="${i}" data-field="${field}" aria-label="Priority ${i+1} ${labels[j]}">${statuses.map(s=>`<option${r[field]===s?' selected':''}>${s}</option>`).join('')}</select>`:['markup','sellThrough','unitsGoal'].includes(field)?`<input type="number" min="0" ${field==='sellThrough'?'max="100"':''} step="${field==='unitsGoal'?'1':'any'}" data-row="${i}" data-field="${field}" value="${esc(r[field])}" aria-label="Priority ${i+1} ${labels[j]}">`:`<textarea data-row="${i}" data-field="${field}" maxlength="2000" aria-label="Priority ${i+1} ${labels[j]}" placeholder="${j===0?'Add a priority…':'Add '+labels[j].toLowerCase()+'…'}">${esc(r[field])}</textarea>`}</td>`).join('')}</tr>`).join('');}
function draft(){localStorage.setItem(planKey(plan.month),JSON.stringify(validatePlan(plan)));}
async function savePlan(value=plan){value=validatePlan(value);if(planMode==='error')throw Error('Shared connection is unavailable. Export a backup of your draft.');if(planMode==='local'){localStorage.setItem(planKey(value.month),JSON.stringify(value));return value;}
  const res=await fetch(`api/priorities?month=${value.month}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)}),body=await res.json();if(!res.ok)throw Error(body.error||'Unable to save shared plan');const result=validatePlan(body);localStorage.setItem(planKey(result.month),JSON.stringify(result));return result;
}
async function saveCurrent(){try{plan=await savePlan();$('planMessage').textContent=planMode==='shared'?'Saved for the team.':'Saved in this browser. Use Backup for another device.';}catch(error){$('planMessage').textContent=error.message;}}
async function carry(){try{plan=await savePlan();const month=nextMonth(plan.month),target=await fetchPlan(month);if(target.mode!==planMode)throw Error('Storage mode changed. Reload before carrying priorities.');const next=carryForward(plan,target.plan);await savePlan(next);$('planMessage').textContent=`Unfinished priorities copied to ${monthNice(month)}. Existing priorities and this month’s results were preserved.`;}catch(error){$('planMessage').textContent=error.message;}}
function auditKey(){return `purchase-review-v1:${data.meta.generatedAt}:${JSON.stringify(filters())}`;}
function loadReviews(){try{reviews=JSON.parse(localStorage.getItem(auditKey())||'{}');}catch{reviews={};}}
const auditId=r=>JSON.stringify([r.store,r.vendor]);
function renderAudit(){$('auditVendors').innerHTML=audit.map((r,i)=>{const review=reviews[auditId(r)],status=review?review.comparisons.some(x=>x.difference!==null&&x.difference!==0)?'Differences recorded':review.comparisons.every(x=>x.difference===0)?'Entered figures match':'Review incomplete':'Not reviewed';return `<article class="audit-card"><h3>${esc(r.vendor)}<small>${esc(r.store)}</small></h3><span class="badge ${status==='Differences recorded'?'bad':status==='Entered figures match'?'good':''}">${status}</span><p>${number(r.unitsIn)} receipt units<br>${number(r.quantityOrdered)} ordered · ${number(r.netItemsSold)} net</p><button class="text-button" data-review="${i}">Compare with Shopify ↗</button></article>`;}).join('');}
function reviewMetrics(r){return [['unitsIn','Units In',r.unitsIn],['dateReceived','Date Received',r.dateReceived.length?r.dateReceived.join(', '):null],['receiptCOGS','COGS Value',r.receiptCOGS],['markup','Markup %',r.markup],...[30,60,90].flatMap(d=>{const complete=r.windows.length&&r.windows.every(g=>g.windows[d].status==='ready');const units=complete?r.windows.reduce((n,g)=>n+g.windows[d].units,0):null;return [[`units${d}`,`${d} Days · Units Sold`,units],[`pct${d}`,`${d} Days · % Sold`,units!==null&&r.unitsIn?100*units/r.unitsIn:null]];})];}
function openReview(index){reviewIndex=index;const r=audit[index],old=reviews[auditId(r)];$('reviewTitle').textContent=`${r.vendor} · ${r.store}`;$('reviewFields').innerHTML=reviewMetrics(r).map(([key,label,value])=>`<label>${label}<small>Dashboard: ${value===null?'Source absent':esc(value)}</small><input name="${key}" ${key==='dateReceived'?'type="text" placeholder="YYYY-MM-DD, …"':'type="number" step="any"'} value="${esc(old?.comparisons.find(x=>x.field===key)?.shopify??'')}"></label>`).join('');$('reviewReference').value=old?.reference||'';$('reviewDialog').showModal();}
function saveReview(event){event.preventDefault();const r=audit[reviewIndex],form=new FormData($('reviewForm'));const comparisons=reviewMetrics(r).map(([field,,dashboard])=>{const raw=String(form.get(field)||'').trim(),shopify=raw===''?null:field==='dateReceived'?raw:Number(raw);return {field,dashboard,shopify,difference:dashboard===null||shopify===null?null:field==='dateReceived'?(dashboard===shopify?0:1):Math.round((dashboard-shopify)*1000000)/1000000};});reviews[auditId(r)]={reference:$('reviewReference').value,checkedAt:new Date().toISOString(),comparisons};localStorage.setItem(auditKey(),JSON.stringify(reviews));$('reviewDialog').close();renderAudit();}
async function init(){try{const get=async url=>{const res=await fetch(url,{cache:'no-store'});if(!res.ok)throw Error(`Could not load ${url} (${res.status})`);return res.json();};const [manifest,cfg]=await Promise.all([get('data/manifest.json'),get('site-config.json')]);config=cfg;if(!/^https?:$/.test(new URL(config.inventoryUrl).protocol))throw Error('Invalid Inventory link');
  const parts=await Promise.all(manifest.files.map(async entry=>{if(!/^purchase_[a-z]+_\d+\.json$/.test(entry.file))throw Error('Invalid data path');return {...entry,rows:await get('data/'+entry.file)};}));data={...parts.find(p=>p.key==='base').rows[0],sales:parts.filter(p=>p.key==='sales').flatMap(p=>p.rows),catalog:parts.filter(p=>p.key==='catalog').flatMap(p=>p.rows)};
  $('sourceDate').textContent=`Shopify · through ${nice(data.asOf)}`;$('buildStamp').textContent=`v1 · source ${data.meta.generatedAt.slice(0,10)}`;options('store',Object.entries(data.meta.stores).map(([value,s])=>({value,label:s.label||value})),'Corro + Cavali');refreshDimensions();refreshPeriods();render();$('planMonth').value=data.asOf.slice(0,7);await loadPlan($('planMonth').value);
  $('store').onchange=()=>{refreshDimensions();render();};$('brand').onchange=()=>{refreshDimensions();render();};$('vendor').onchange=render;$('periodType').onchange=()=>{refreshPeriods();render();};$('period').onchange=render;$('reset').onclick=()=>{$('store').value='all';$('brand').value='all';$('vendor').value='all';$('periodType').value='month';refreshDimensions();refreshPeriods();attention=false;$('onlyAttention').setAttribute('aria-pressed','false');render();};
  $('onlyAttention').onclick=()=>{attention=!attention;$('onlyAttention').setAttribute('aria-pressed',String(attention));renderReceipts();};$('sourceOpen').onclick=openSources;$('exportReceipts').onclick=exportReceipts;
  $('planMonth').onchange=()=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test($('planMonth').value))loadPlan($('planMonth').value);};$('planRows').oninput=event=>{const {row,field}=event.target.dataset;if(row===undefined)return;plan.rows[Number(row)][field]=event.target.value;try{draft();$('planMessage').textContent=planMode==='shared'?'Draft saved locally. Click Save plan to update the team.':'Draft saved in this browser.';}catch(error){$('planMessage').textContent=error.message;}};
  $('planRows').onclick=event=>{const toggle=event.target.closest('[data-toggle]');if(!toggle)return;const row=toggle.closest('tr');row.classList.toggle('expanded');toggle.setAttribute('aria-expanded',String(row.classList.contains('expanded')));};
  $('savePlan').onclick=saveCurrent;$('carryPlan').onclick=carry;$('exportPlan').onclick=()=>{try{download(`purchase-priorities-${plan.month}.json`,validatePlan(plan));}catch(error){$('planMessage').textContent=error.message;}};$('importPlan').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>100000)throw Error('Plan file is too large');const incoming=validatePlan(JSON.parse(await file.text()));if(incoming.month!==plan.month)throw Error('Select the matching plan month before importing.');plan={...incoming,version:plan.version};draft();renderPlan();$('planMessage').textContent='Imported as a draft. Click Save plan to apply it.';}catch(error){$('planMessage').textContent=error.message;}event.target.value='';};
  $('auditVendors').onclick=event=>{const btn=event.target.closest('[data-review]');if(btn)openReview(Number(btn.dataset.review));};$('closeReview').onclick=()=>$('reviewDialog').close();$('reviewForm').onsubmit=saveReview;$('exportAudit').onclick=()=>download(`purchase-vendor-review-${filters().period}.json`,{source:data.meta.generatedAt,filters:filters(),sample:audit,manualShopifyReview:reviews});
  }catch(error){$('sourceNote').textContent=`Unable to load the report: ${error.message}. Restore a complete export and rebuild; previous data is not substituted.`;$('sourceDate').textContent='Data load failed';console.error(error);}}
try{document.documentElement.dataset.theme=localStorage.getItem('purchase-theme')||'light';}catch{}$('theme').onclick=()=>{const value=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=value;try{localStorage.setItem('purchase-theme',value);}catch{}};
init();
